ALTER TABLE purchase_orders ENABLE TRIGGER trg_purchase_orders_set_updated_at;

-- Document numbers were issued explicitly: move the counters to the highest number of each year.
UPDATE number_ranges SET last_value = 291
 WHERE document_type = 'invoice_receipt' AND fiscal_year = 2025;
UPDATE number_ranges SET last_value = 1140
 WHERE document_type = 'invoice_receipt' AND fiscal_year = 2026;
UPDATE number_ranges SET last_value = 273
 WHERE document_type = 'payment' AND fiscal_year = 2025;
UPDATE number_ranges SET last_value = 1109
 WHERE document_type = 'payment' AND fiscal_year = 2026;

-- Sequences continue after the explicit ids.
SELECT setval(pg_get_serial_sequence('invoice_receipts', 'id'), (SELECT max(id) FROM invoice_receipts));
SELECT setval(pg_get_serial_sequence('invoice_receipt_items', 'id'), (SELECT max(id) FROM invoice_receipt_items));
SELECT setval(pg_get_serial_sequence('payments', 'id'), (SELECT max(id) FROM payments));

DO $$
DECLARE
    t record;
BEGIN
    FOR t IN
        SELECT tgrelid::regclass AS table_name, tgname
          FROM pg_trigger
         WHERE tgfoid = 'audit_row_change'::regproc
           AND NOT tgisinternal
    LOOP
        EXECUTE format('ALTER TABLE %s ENABLE TRIGGER %I', t.table_name, t.tgname);
    END LOOP;
END;
$$;

COMMIT;
